          end

          case ( _exp_gps_baseband_rtl1_tessent_edt_c1_inst__chain_60_sobus[_bit_count] )
            1'b1: begin
                    $fwrite(_diag_file, " H"); 
                  end
            1'b0: begin
                    $fwrite(_diag_file, " L"); 
                  end
            1'bZ: begin
                    $fwrite(_diag_file, " Z"); 
                  end
          endcase
          case ( _sim_gps_baseband_rtl1_tessent_edt_c1_inst__chain_60_sobus[_bit_count] )
            1'b1: begin
                    $fwrite(_diag_file, " H  // %s\n", _name_sobus[(_gps_baseband_rtl1_tessent_edt_c1_inst__chain_60_start+_bit_count)]);
